function imageHandoffPackageCustodyLedgerEntries(summary: ImageLinksSummary, scope: string, details: ImageHandoffDetail[]): Array<{ stage: string; actor: string; status: 'closed' | 'ready' | 'hold' | 'pending'; detail: string; evidence: string; nextAction: string }> {
  const deliveryReceipt = imageHandoffPackageDeliveryReceiptPayload(summary, scope, details) as { receiptStatus?: string; holdCount?: number; pendingAcceptanceCount?: number };
  const closeout = imageHandoffPackageCloseoutCertificatePayload(summary, scope, details) as { closeoutStatus?: string; holdCount?: number; pendingCount?: number };
  const archiveManifest = imageHandoffPackageArchiveManifestPayload(summary, scope, details) as { archiveStatus?: string; holdCount?: number; pendingCount?: number };
  const retrievalRequest = imageHandoffPackageRetrievalRequestPayload(summary, scope, details) as { retrievalStatus?: string; holdCount?: number; pendingCount?: number };
  const retrievalFulfillment = imageHandoffPackageRetrievalFulfillmentPayload(summary, scope, details) as { fulfillmentStatus?: string; holdCount?: number; pendingCount?: number };
  const returnReceipt = imageHandoffPackageRetrievalReturnReceiptPayload(summary, scope, details) as { returnStatus?: string; holdCount?: number; pendingCount?: number };
  return [
    { stage: 'Delivery custody accepted', actor: 'Recipient', status: deliveryReceipt.receiptStatus === 'ready for recipient signature' ? 'ready' : (deliveryReceipt.holdCount ?? 0) > 0 ? 'hold' : 'pending', detail: (deliveryReceipt.holdCount ?? 0) + ' delivery hold(s), ' + (deliveryReceipt.pendingAcceptanceCount ?? 0) + ' pending acceptance item(s).', evidence: 'image-package-delivery-receipt.md', nextAction: 'Capture recipient signature and delivery receipt evidence.' },
    { stage: 'Closeout custody certified', actor: 'Archive owner', status: closeout.closeoutStatus === 'certified' ? 'closed' : (closeout.holdCount ?? 0) > 0 ? 'hold' : 'pending', detail: (closeout.holdCount ?? 0) + ' closeout hold(s), ' + (closeout.pendingCount ?? 0) + ' pending closeout item(s).', evidence: 'image-package-closeout-certificate.md', nextAction: 'Certify closeout before archive freeze.' },
    { stage: 'Archive custody frozen', actor: 'Archive owner', status: archiveManifest.archiveStatus === 'archived' ? 'closed' : (archiveManifest.holdCount ?? 0) > 0 ? 'hold' : 'pending', detail: (archiveManifest.holdCount ?? 0) + ' archive hold(s), ' + (archiveManifest.pendingCount ?? 0) + ' pending archive item(s).', evidence: 'image-package-archive-manifest.json', nextAction: 'Freeze archive packet with file index, audit, and retention fields.' },
    { stage: 'Retrieval custody requested', actor: 'Requester', status: retrievalRequest.retrievalStatus === 'ready' ? 'ready' : (retrievalRequest.holdCount ?? 0) > 0 ? 'hold' : 'pending', detail: (retrievalRequest.holdCount ?? 0) + ' retrieval hold(s), ' + (retrievalRequest.pendingCount ?? 0) + ' pending retrieval item(s).', evidence: 'image-package-retrieval-request.md', nextAction: 'Approve requester, purpose, release date, and return due date.' },
    { stage: 'Retrieval custody fulfilled', actor: 'Archive owner', status: retrievalFulfillment.fulfillmentStatus === 'fulfilled' ? 'closed' : (retrievalFulfillment.holdCount ?? 0) > 0 ? 'hold' : 'pending', detail: (retrievalFulfillment.holdCount ?? 0) + ' fulfillment hold(s), ' + (retrievalFulfillment.pendingCount ?? 0) + ' pending fulfillment item(s).', evidence: 'image-package-retrieval-fulfillment.md', nextAction: 'Verify restored files and hand off to custody recipient.' },
    { stage: 'Retrieval custody returned', actor: 'Final custodian', status: returnReceipt.returnStatus === 'closed' ? 'closed' : (returnReceipt.holdCount ?? 0) > 0 ? 'hold' : 'pending', detail: (returnReceipt.holdCount ?? 0) + ' return hold(s), ' + (returnReceipt.pendingCount ?? 0) + ' pending return item(s).', evidence: 'image-package-retrieval-return-receipt.md', nextAction: 'Close custody after return, re-freeze, or destroy-after-use proof.' },
  ];
}

