function imageHandoffPackageCustodyExceptionItems(summary: ImageLinksSummary, scope: string, details: ImageHandoffDetail[]): Array<{ exception: string; owner: string; severity: 'critical' | 'hold' | 'review'; detail: string; evidence: string; remediation: string }> {
  const ledger = imageHandoffPackageCustodyLedgerPayload(summary, scope, details) as { custodyStatus?: string; holdCount?: number; pendingCount?: number; entries?: Array<{ stage?: string; actor?: string; status?: string; detail?: string; evidence?: string; nextAction?: string }> };
  const releaseGate = imageHandoffPackageReleaseGatePayload(summary, scope, details) as { releaseStatus?: string; holdCount?: number };
  const entries = ledger.entries ?? [];
  const exceptions: Array<{ exception: string; owner: string; severity: 'critical' | 'hold' | 'review'; detail: string; evidence: string; remediation: string }> = entries
    .filter((entry) => entry.status === 'hold' || entry.status === 'pending')
    .map((entry) => ({
      exception: entry.stage ?? 'Custody stage exception',
      owner: entry.actor ?? 'Custody owner',
      severity: entry.status === 'hold' ? 'hold' as const : 'review' as const,
      detail: entry.detail ?? 'Custody evidence requires review.',
      evidence: entry.evidence ?? 'image-package-custody-ledger.md',
      remediation: entry.nextAction ?? 'Complete missing custody evidence and update ledger.',
    }));
  if (releaseGate.releaseStatus !== 'ready') {
    exceptions.push({ exception: 'Release gate custody blocker', owner: 'Release manager', severity: 'critical', detail: (releaseGate.holdCount ?? 0) + ' release hold(s) still affect custody closure.', evidence: 'image-package-release-gate.md', remediation: 'Clear release gate holds before final custody signoff.' });
  }
  if (exceptions.length === 0) {
    return [{ exception: 'No custody exceptions detected', owner: 'Archive owner', severity: 'review', detail: 'Custody ledger has no holds or pending items at generation time.', evidence: 'image-package-custody-ledger.json', remediation: 'Perform final human audit before closing custody.' }];
  }
  return exceptions;
}

function imageHandoffPackageCustodyExceptionsPayload(summary: ImageLinksSummary, scope: string, details: ImageHandoffDetail[]): Record<string, unknown> {
  const exceptions = imageHandoffPackageCustodyExceptionItems(summary, scope, details);
  const criticalCount = exceptions.filter((item) => item.severity === 'critical').length;
  const holdCount = exceptions.filter((item) => item.severity === 'hold').length;
  const reviewCount = exceptions.filter((item) => item.severity === 'review').length;
  return {
    scope,
    generatedBy: 'AnchorWorks',
    reportType: 'Image package custody exceptions',
    exceptionStatus: criticalCount === 0 && holdCount === 0 ? 'review' : criticalCount > 0 ? 'critical' : 'hold',
    criticalCount,
    holdCount,
    reviewCount,
    auditOwner: '',
    remediationDue: '',
    exceptions,
  };
}

